ForeverGuides.ProfessionData["fishing"] = {
  gather={
    {from=1,items={6256,6529,6291},note={de="Angelrute und Glänzende Schmuckstücke (+25) beim Händler kaufen, Rute anlegen, auswerfen und beim Platschen anklicken. Bis 75 im Startgewässer bleiben und rohen Fisch für die Kochkunst aufheben.",en="Buy a fishing pole and shiny baubles (+25) from the vendor, equip the pole, cast and click on the splash. Stay in the starting water until 75 and keep raw fish for cooking."},to=75,where={de="Euer Startgewässer (Wald von Elwynn, Mulgore, Durotar, Dun Morogh, Tirisfal oder Teldrassil)",en="Your starting water (Elwynn Forest, Mulgore, Durotar, Dun Morogh, Tirisfal or Teldrassil)"}},
    {from=75,items={6530,6291},note={de="Schon ab Skill 50 und Charakterstufe 10 den Gesellenrang lernen. Entkommen oft Fische, helfen Nachtkriecher (+50, ab Skill 50). Köder erhöhen nur zeitweise die effektive Fertigkeit.",en="Learn Journeyman as early as skill 50 and character level 10. If fish escape often, nightcrawlers help (+50, from skill 50). Bait only raises your effective skill for a while."},to=150,where={de="Gewässer in den Hauptstädten (Sturmwind, Orgrimmar, Donnerfels, Unterstadt, Darnassus)",en="Waters in the capitals (Stormwind, Orgrimmar, Thunder Bluff, Undercity, Darnassus)"}},
    {from=150,items={6532,6308,8365},note={de="Vor dem Limit bei 150 das Expertenbuch lesen (ab Skill 125 und Charakterstufe 20). Helle Schmuckstücke (+75, ab Skill 100) halten Fische an der Rute. Stachelbartwels und Mithrilkopfforelle für die Kochkunst aufheben.",en="Read the expert book before the cap at 150 (from skill 125 and character level 20). Bright baubles (+75, from skill 100) keep fish on the line. Keep catfish and trout for cooking."},to=225,where={de="Düstermarschen (innere Seen, bequem für den späteren Besuch bei Nat Pagle) oder Schlingendorntal",en="Dustwallow Marsh (inner lakes, convenient for the later visit to Nat Pagle) or Stranglethorn Vale"}},
    {from=225,items={16967,16970,16968,16969,13760,13759},note={de="Mit Skill 225 und Stufe 35 bei Nat Pagle die Quest annehmen und die vier Questfische fangen, danach geht es weiter bis 300. Nutzt Köder: die meisten höheren Gewässer brauchen effektiv etwa 300 für sichere Fänge. Sonnenschuppenlachs und Nachtflossenschnapper für die letzten Kochpunkte aufheben.",en="At skill 225 and level 35, accept the quest from Nat Pagle and catch the four quest fish; after that you continue to 300. Use bait: most higher waters need about 300 effective skill for safe catches. Keep sunscale salmon and nightfin snapper for the last cooking points."},to=300,where={de="Feralas (Binnengewässer, nicht der Jademirsee); Questfische: Feralas (Binnenwasser), östliche Küste der Sümpfe des Elends, westliche Küste von Desolace, Westküste des Schlingendorntals",en="Feralas (fresh water, not Lake Jademir); quest fish: Feralas (inland water), east coast of the Swamp of Sorrows, west coast of Desolace, west coast of Stranglethorn Vale"}},
  },
  intro={de="Beim Angeln zählt jeder erfolgreiche Fang, nicht die Schwierigkeit des Gewässers. Ein hohes effektives Angelniveau durch Rute, Köder oder Essen verhindert entkommende Fische, überspringt aber keinen Rang. Zwei Hürden: Den Expertenrang kauft ihr als Buch, den Fachmannrang schaltet eine Quest bei Nat Pagle frei.",en="Every successful catch counts in fishing, not the difficulty of the water. A high effective fishing level from pole, bait or food stops fish from escaping but does not skip a rank. Two gates: you buy the Expert rank as a book, and a quest with Nat Pagle unlocks Artisan."},
